<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { listen, type UnlistenFn } from '@tauri-apps/api/event'
import { isTauri } from '@tauri-apps/api/core'
import { save as saveFileDialog } from '@tauri-apps/plugin-dialog'
import AppIcon from './AppIcon.vue'
import ViewportSelect from './ViewportSelect.vue'
import { toolbox, type ModuleSummary } from '../services/toolbox'
import { createToolRepository, repositoryClient, repositoryError, repositoryRoutes, repositorySize, repositorySource, type RepositoryProgress } from '../services/toolRepository'

const props = defineProps<{ refreshTools: () => Promise<void>; canPresent: boolean }>()
const emit = defineEmits<{ open: [id: string]; 'busy-change': [busy: boolean, installing: boolean]; notify: [message: string] }>()
const dialog = ref<HTMLDialogElement | null>(null), title = ref<HTMLElement | null>(null), openTools = ref<ModuleSummary | null>(null)
let disposed = false, unlisten: UnlistenFn | undefined
let pendingPrompt: (() => void) | undefined
async function chooseSavePath(name: string) {
  if (!props.canPresent) await new Promise<void>(resolve => {
    const stop = watch(() => props.canPresent, ready => { if (ready) { stop(); pendingPrompt = undefined; resolve() } })
    pendingPrompt = () => { stop(); resolve() }
  })
  if (disposed) return null
  const android = navigator.userAgent.includes('Android')
  // The native dialog confirms overwriting this exact path. Changing it afterward
  // could silently replace a different file that the user never confirmed.
  return saveFileDialog({ title: '保存 .fftool 工具包', defaultPath: name, ...(android ? {} : { filters: [{ name: '流萤工具包', extensions: ['fftool'] }] }) })
}
const m = createToolRepository({ ...repositoryClient, listInstalled: toolbox.listModules, refreshTools: props.refreshTools, chooseSavePath, notify: message => emit('notify', message) })
const { route, catalog, loading, query, category, categories, entries, metadataPending, metadataFailed, phase, busy, activeEntry, prepared, reviewOpen, allowNetwork, progress } = m
const percent = computed(() => progress.total ? Math.min(100, Math.floor(progress.received / progress.total * 100)) : 0)
const canInstall = computed(() => prepared.value?.summary && prepared.value.compatible && !busy.value && (!prepared.value.summary.network_hosts.length || allowNetwork.value))
function date(value: number | string) { const time = new Date(typeof value === 'number' ? value * 1000 : value); return Number.isFinite(time.getTime()) ? time.toLocaleString('zh-CN', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : '' }
async function openLink(url: string) { try { await repositoryClient.openLink(url) } catch (reason) { if (!disposed) emit('notify', repositoryError(reason)) } }
function openInstalled(summary: ModuleSummary) {
  if (summary.tool_ids.length === 1) emit('open', summary.tool_ids[0]!)
  else openTools.value = summary
}
function closeDialog() { if (busy.value) return; openTools.value = null; m.closeReview() }
function handleBack() { if (reviewOpen.value || openTools.value) { closeDialog(); return true }; return false }
defineExpose({ handleBack })
watch([reviewOpen, openTools, () => props.canPresent], async () => {
  await nextTick()
  if (disposed) return
  const shouldShow = (reviewOpen.value || openTools.value) && props.canPresent
  if (shouldShow && !dialog.value?.open && !document.querySelector('dialog[open]')) { dialog.value?.showModal(); title.value?.focus({ preventScroll: true }) }
  else if (!shouldShow && dialog.value?.open) dialog.value.close()
}, { flush: 'post' })
watch([busy, phase], () => emit('busy-change', busy.value, phase.value === 'installing'))
onMounted(async () => {
  if (isTauri()) {
    try { const stop = await listen<RepositoryProgress>('firefly:repository-progress', event => m.onProgress(event.payload)); if (disposed) stop(); else unlisten = stop } catch { /* Completion/error feedback still works. */ }
  }
  if (!disposed) void m.load()
})
onBeforeUnmount(() => { disposed = true; pendingPrompt?.(); unlisten?.(); m.dispose(); dialog.value?.close(); emit('busy-change', false, false) })
</script>

<template>
  <section class="content-section first-section tool-download-page" aria-label="工具市场">
    <header class="repository-heading"><span class="repository-heading-icon"><AppIcon name="download" /></span><div><h1>FFTools 工具市场</h1><p>从官方公开仓库获取的最新工具，下载后请仔细核对内容再安装使用。</p></div><button class="repository-source-button" type="button" @click="openLink(repositorySource(catalog))"><AppIcon name="module-code" /><span>从外部浏览器访问</span><span aria-hidden="true">↗</span></button></header>
    <div class="repository-toolbar">
      <label class="repository-search"><AppIcon name="module-search" /><input v-model="query" type="search" aria-label="搜索工具" placeholder="搜索工具名、文件名或关键字" /></label>
      <div class="repository-route"><label for="repository-route">访问线路</label><ViewportSelect id="repository-route" :model-value="route" :options="repositoryRoutes" ariaLabel="访问线路" :disabled="busy || loading" @update:model-value="m.setRoute" /></div>
      <button class="secondary-button repository-refresh" type="button" :disabled="loading || busy" @click="m.load(true)"><AppIcon name="sync" />{{ loading ? '正在刷新…' : '刷新列表' }}</button>
    </div>
    <details class="repository-route-help"><summary>线路说明</summary><p>自动模式优先尝试免费加速，失败后尝试其他加速服务或官方直连；可手动切换 GH-Proxy 或 GitHub。第三方仅接收公开仓库的访问请求，不传输账号令牌。文件会与当前仓库索引核对，校验一致不代表工具已通过安全审核。</p><div><button class="text-button" type="button" @click="openLink('https://gh-proxy.com/docs/github-accelerator')">GH-Proxy</button><button class="text-button" type="button" @click="openLink('https://ghfast.top')">GHFast</button><button class="text-button" type="button" @click="openLink('https://www.jsdelivr.com/')">jsDelivr</button></div></details>
    <div v-if="catalog" class="repository-catalog-info"><span>{{ catalog.from_cache ? '本机缓存' : '目录已更新' }} · {{ date(catalog.fetched_at) }}<span v-if="catalog.source"> · {{ catalog.source }}</span></span><span v-if="metadataPending" role="status">正在读取工具名称 {{ metadataPending }} 项…</span><span v-else-if="metadataFailed">部分名称暂无法读取，可刷新重试。</span></div>
    <details v-if="catalog?.skipped_entries?.length" class="repository-route-help repository-skipped"><summary>已跳过 {{ catalog.skipped_entries.length }} 个异常工具包</summary><p>这些文件暂不可用，其余工具可正常下载。</p><ul><li v-for="item in catalog.skipped_entries" :key="item.path"><strong>{{ item.path }}</strong><span>{{ item.reason }}</span></li></ul></details>
    <div v-if="busy" class="repository-operation" role="status"><div><strong>{{ phase === 'downloading' ? percent === 100 ? '正在检查工具包…' : '正在下载工具包…' : phase === 'installing' ? '正在安装工具…' : '正在保存文件…' }}</strong><span>{{ activeEntry?.title }}<template v-if="phase === 'downloading'"> · {{ repositorySize(progress.received) }} / {{ repositorySize(progress.total) }}<span v-if="progress.source"> · {{ progress.source }}</span></template></span></div><progress v-if="phase === 'downloading'" :value="progress.received" :max="progress.total" aria-label="工具包下载进度"></progress><button v-if="phase === 'downloading'" class="secondary-button" type="button" @click="m.cancel">取消下载</button></div>
    <nav v-if="catalog" class="repository-categories" aria-label="工具分类"><button type="button" :class="{ selected: !category }" :aria-pressed="!category" @click="category = ''">全部<span>{{ catalog.entries.length }}</span></button><button v-for="name in categories" :key="name" type="button" :class="{ selected: category === name }" :aria-pressed="category === name" @click="category = name">{{ name }}<span>{{ catalog.entries.filter(item => item.category === name).length }}</span></button></nav>
    <div v-if="entries.length" class="repository-grid">
      <article v-for="item in entries" :key="item.id" class="repository-card" :data-entry-id="item.id">
        <div class="repository-card-heading"><span class="repository-card-icon"><AppIcon :name="item.category.includes('图片') ? 'module-image' : item.category.includes('查询') ? 'module-globe' : 'module-file'" /></span><div><h2>{{ item.title }}</h2><span>{{ item.category }}</span></div><span v-if="m.installedFor(item)" class="repository-installed-badge">已安装</span></div>
        <p v-if="item.description" class="repository-description">{{ item.description }}</p>
        <p class="repository-file-name">{{ item.file_name }}</p>
        <div class="repository-card-meta"><span>{{ repositorySize(item.size) }}<template v-if="item.version_hint"> · v{{ item.version_hint }}</template></span><span v-if="item.updated_at">{{ date(item.updated_at) }}</span><button class="text-button" type="button" @click="openLink(repositorySource(catalog, item))">查看来源 ↗</button></div>
        <div v-if="m.installedFor(item)" class="repository-local-version"><span>本机 v{{ m.installedFor(item)!.version }} · {{ m.installedFor(item)!.tools.length }} 个工具</span><button class="text-button" type="button" :disabled="busy" @click="openInstalled(m.installedFor(item)!)">打开工具</button></div>
        <div class="repository-card-actions"><button class="secondary-button" type="button" :disabled="busy || loading" @click="m.start(item, 'save')">下载文件</button><button class="primary-button" type="button" :disabled="busy || loading" @click="m.start(item, 'install')"><AppIcon name="download" />{{ m.installedFor(item) ? '检查并安装' : '下载并安装' }}</button></div>
      </article>
    </div>
    <div v-else class="repository-empty"><AppIcon :name="loading ? 'sync' : 'download'" /><strong>{{ loading && !catalog ? '正在连接工具仓库…' : query || category ? '暂未找到匹配的工具' : catalog ? '仓库里暂时没有可用工具包' : '工具列表暂时无法加载' }}</strong><p>{{ metadataPending ? '正在补全工具名称，可稍候或按文件名搜索。' : query || category ? '换一个关键字或分类试试。' : '可刷新列表或切换访问线路。' }}</p><button v-if="query || category" class="text-button" type="button" @click="query = ''; category = ''">清除筛选</button></div>
    <dialog ref="dialog" class="detect-dialog repository-dialog" aria-labelledby="repository-dialog-title" @cancel.prevent="closeDialog">
      <template v-if="openTools"><div class="dialog-heading"><h2 id="repository-dialog-title" ref="title" tabindex="-1">打开工具</h2><button class="icon-button" type="button" aria-label="关闭工具选择" @click="closeDialog">×</button></div><p class="module-hint">{{ openTools.name }}</p><div class="repository-open-tools"><button v-for="(id, index) in openTools.tool_ids" :key="id" class="secondary-button" type="button" @click="$emit('open', id)">{{ openTools.tools[index] || id }}<AppIcon name="chevron-right" /></button></div></template>
      <template v-else-if="prepared"><div class="dialog-heading"><h2 id="repository-dialog-title" ref="title" tabindex="-1">{{ prepared.summary?.name || activeEntry?.title || prepared.file_name }}</h2><button class="icon-button" type="button" :disabled="busy" aria-label="关闭安装预览" @click="closeDialog">×</button></div>
        <p v-if="prepared.description" class="module-hint">{{ prepared.description }}</p>
        <p class="repository-verified"><AppIcon name="check" />文件与仓库索引一致 · {{ prepared.cached ? '本机下载缓存' : prepared.source }}</p>
        <dl class="repository-review-meta"><template v-if="prepared.summary"><div><dt>版本</dt><dd>v{{ prepared.summary.version }}<template v-if="prepared.installed_version"> · 本机 v{{ prepared.installed_version }}</template></dd></div><div><dt>作者</dt><dd>{{ prepared.summary.author }}</dd></div><div><dt>许可证</dt><dd>{{ prepared.license }}</dd></div><div><dt>适用平台</dt><dd>{{ prepared.platforms.join(' · ') }}</dd></div><div><dt>工具包 ID</dt><dd>{{ prepared.summary.module_id }}</dd></div></template><div><dt>文件</dt><dd>{{ prepared.file_name }} · {{ repositorySize(prepared.bytes) }}</dd></div></dl>
        <div v-if="prepared.summary" class="repository-contained-tools"><strong>包含的工具</strong><span v-for="(name, index) in prepared.summary.tools" :key="index">{{ name }}</span></div>
        <template v-if="prepared.summary?.network_hosts.length"><details class="repository-network"><summary>需要联网（{{ prepared.summary.network_hosts.length }} 个来源）</summary><ul><li v-for="host in prepared.summary.network_hosts" :key="host">{{ host }}</li></ul></details><label class="repository-consent"><input v-model="allowNetwork" type="checkbox" :disabled="busy" />允许此工具使用以上联网来源</label></template><p v-else-if="prepared.summary" class="module-hint">此工具未声明联网来源。</p>
        <p v-if="prepared.inspection_error" class="error-text" role="alert">{{ prepared.inspection_error }}</p>
        <div class="repository-review-warnings"><p v-if="prepared.installed_version && prepared.compatible" class="repository-warning repository-overwrite">安装将覆盖本机同 ID 的工具定义，请确认是否保留过本地源码修改。</p><p class="repository-warning repository-script-warning">工具包含可执行脚本，安装前请核对作者、工具内容及联网来源。安装完成后仍停留在本页。</p></div>
        <div class="dialog-actions repository-review-actions"><button class="secondary-button" type="button" :disabled="busy" @click="closeDialog">取消</button><button class="secondary-button" type="button" :disabled="busy" @click="m.save">保存文件</button><button class="primary-button" type="button" :disabled="!canInstall" @click="m.install">{{ phase === 'installing' ? '正在安装…' : prepared.installed_version ? '覆盖安装' : '安装工具' }}</button></div>
      </template>
    </dialog>
  </section>
</template>

<style>
.tool-download-page { max-width: 1100px; min-width: 0; }
.repository-heading { display: flex; align-items: center; flex-wrap: wrap; gap: 14px; padding: 22px; border: 1px solid var(--border); border-radius: 21px; background: linear-gradient(120deg, var(--accent-soft), var(--surface)); }
.repository-heading-icon { display: grid; place-items: center; flex: 0 0 48px; width: 48px; height: 48px; border: 1px solid var(--border); border-radius: 16px; color: var(--accent); background: var(--surface); }
.repository-heading-icon svg { width: 25px; height: 25px; }.repository-heading h1 { margin: 0; font-size: calc(23px * var(--app-font-scale)); }.repository-heading p { margin: 5px 0 0; color: var(--muted); font-size: calc(12px * var(--app-font-scale)); line-height: 1.6; }
.repository-source-button { display: inline-flex; align-items: center; gap: 8px; min-height: 42px; margin-left: auto; padding: 9px 12px; border: 1px solid var(--border); border-radius: 11px; background: var(--surface); color: var(--accent); font-size: calc(12px * var(--app-font-scale)); }.repository-source-button svg { width: 17px; height: 17px; }
.repository-toolbar { display: grid; grid-template-columns: minmax(180px, 1fr) minmax(210px, 260px) auto; align-items: end; gap: 14px; margin-top: 22px; }
.repository-search { display: flex; align-items: center; gap: 10px; height: 48px; min-width: 0; padding: 0 13px; border: 1px solid var(--border); border-radius: 12px; background: var(--surface); }.repository-search svg { flex: 0 0 19px; width: 19px; height: 19px; color: var(--muted); }.repository-search input { width: 100%; min-width: 0; height: 44px; border: 0; outline: 0; background: transparent; color: var(--text); font: inherit; font-size: calc(14px * var(--app-font-scale)); }
.repository-search:focus-within { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }
.repository-search input:focus, .repository-search input:focus-visible { border: 0; outline: none; box-shadow: none; }
.repository-route > label { display: block; margin-bottom: 7px; color: var(--muted); font-size: calc(12px * var(--app-font-scale)); }.repository-route .viewport-select-trigger { width: 100%; min-height: 48px; }.repository-refresh { display: flex; align-items: center; justify-content: center; gap: 8px; white-space: nowrap; }.repository-refresh svg { width: 17px; height: 17px; }
.repository-route-help { margin: 16px 0; border: 1px solid var(--border); border-radius: 14px; background: var(--surface); color: var(--muted); font-size: calc(12px * var(--app-font-scale)); line-height: 1.7; }.repository-route-help summary { padding: 14px 16px; cursor: pointer; color: var(--text); font-weight: 650; }.repository-route-help p { margin: 0 16px 12px; }.repository-route-help > div { display: flex; flex-wrap: wrap; gap: 14px; margin: 0 16px 16px; }
.repository-catalog-info { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 6px 16px; margin-bottom: 12px; color: var(--muted); font-size: calc(11px * var(--app-font-scale)); line-height: 1.6; }
.repository-operation { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px 16px; align-items: center; margin: 16px 0; padding: 16px; border: 1px solid var(--border); border-radius: 14px; background: var(--accent-soft); }.repository-operation > div { display: grid; gap: 5px; min-width: 0; }.repository-operation strong { font-size: calc(14px * var(--app-font-scale)); }.repository-operation span { overflow-wrap: anywhere; color: var(--muted); font-size: calc(12px * var(--app-font-scale)); }.repository-operation progress { grid-column: 1; width: 100%; height: 6px; accent-color: var(--accent); }.repository-operation button { grid-column: 2; grid-row: 1 / span 2; }
.repository-categories { display: flex; flex-wrap: wrap; gap: 9px; margin: 18px 0; }.repository-categories button { display: flex; align-items: center; gap: 8px; min-height: 44px; padding: 8px 13px; border: 1px solid var(--border); border-radius: 999px; background: var(--surface); color: var(--muted); font-size: calc(12px * var(--app-font-scale)); }.repository-categories button.selected { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); }.repository-categories span { font-size: .9em; opacity: .8; }
.repository-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }.repository-card { display: flex; flex-direction: column; min-width: 0; padding: 20px; border: 1px solid var(--border); border-radius: 18px; background: var(--surface); box-shadow: 0 5px 20px #142c2108; }.repository-card-heading { display: flex; align-items: center; gap: 11px; min-width: 0; }.repository-card-icon { display: grid; place-items: center; flex: 0 0 42px; width: 42px; height: 42px; border-radius: 13px; background: var(--accent-soft); color: var(--accent); }.repository-card-icon svg { width: 22px; height: 22px; }.repository-card-heading > div { min-width: 0; }.repository-card h2 { margin: 0 0 5px; font-size: calc(16px * var(--app-font-scale)); line-height: 1.4; overflow-wrap: anywhere; }.repository-card-heading > div > span { color: var(--muted); font-size: calc(11px * var(--app-font-scale)); }.repository-installed-badge { margin-left: auto; flex-shrink: 0; padding: 5px 7px; border-radius: 8px; background: var(--accent-soft); color: var(--accent); font-size: calc(10px * var(--app-font-scale)); }
.repository-description { display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; margin: 12px 0 0; color: var(--muted); font-size: calc(12px * var(--app-font-scale)); line-height: 1.65; white-space: pre-line; }.repository-file-name { margin: 14px 0 8px; color: var(--muted); font: calc(11px * var(--app-font-scale))/1.6 Consolas, monospace; overflow-wrap: anywhere; }.repository-card-meta { display: flex; flex-wrap: wrap; align-items: center; gap: 4px 10px; margin-bottom: 13px; color: var(--muted); font-size: calc(11px * var(--app-font-scale)); }.repository-card-meta .text-button { margin-left: auto; font-size: inherit; min-height: 32px; padding: 4px 0; }
.repository-local-version { display: flex; align-items: center; flex-wrap: wrap; gap: 5px 12px; margin-top: auto; padding: 7px 0 12px; color: var(--muted); font-size: calc(11px * var(--app-font-scale)); }.repository-local-version button { margin-left: auto; font-size: inherit; min-height: 32px; }.repository-card-actions { display: flex; justify-content: flex-end; flex-wrap: wrap; gap: 9px; margin-top: auto; padding-top: 14px; border-top: 1px solid var(--border); }.repository-card-actions button { display: inline-flex; align-items: center; justify-content: center; gap: 7px; min-height: 44px; font-size: calc(13px * var(--app-font-scale)); }.repository-card-actions svg { width: 17px; height: 17px; flex-shrink: 0; }
.repository-empty { display: grid; justify-items: center; gap: 12px; padding: 55px 20px; text-align: center; color: var(--muted); }.repository-empty > svg { width: 40px; height: 40px; color: var(--accent); }.repository-empty strong { color: var(--text); font-size: calc(16px * var(--app-font-scale)); }.repository-empty p { margin: 0; font-size: calc(13px * var(--app-font-scale)); line-height: 1.6; }
.repository-dialog { width: min(600px, calc(100vw - 24px)); max-height: calc(100dvh - var(--safe-top, 0px) - var(--safe-bottom, 0px) - 32px); }.repository-dialog h2 { margin: 0; font-size: calc(21px * var(--app-font-scale)); line-height: 1.4; overflow-wrap: anywhere; }.repository-dialog h2:focus { outline: none; }.repository-dialog .icon-button { flex: 0 0 44px; min-height: 44px; }.repository-verified { display: flex; align-items: center; gap: 7px; margin: 18px 0; color: var(--accent); font-size: calc(12px * var(--app-font-scale)); }.repository-verified svg { width: 17px; height: 17px; }
.repository-review-meta { display: grid; gap: 10px; padding: 15px; border: 1px solid var(--border); border-radius: 13px; background: var(--background); }.repository-review-meta > div { display: grid; grid-template-columns: 78px minmax(0, 1fr); gap: 10px; font-size: calc(12px * var(--app-font-scale)); line-height: 1.6; }.repository-review-meta dt { color: var(--muted); }.repository-review-meta dd { margin: 0; overflow-wrap: anywhere; }
